# Cell 4: Generation Evaluation (exact match, bigram overlap, avg length, clinical-echo)
print("=== GENERATION EVALUATION ===")
gen_all=[]
for lang in LANGS:
    rows = load_split(lang, SPLIT)
    if not rows:
        print(f"[WARN] No rows for {lang}/{SPLIT}")
        continue
    eval_rows = rows[:LIMIT] if LIMIT is not None else rows
    exact=sims_sum=lens_cnt=echo_hits_total=errors=0
    src_counts={}
    for r in eval_rows:
        msg = r.get('instruction') or r.get('input') or r.get('msg') or ''
        ref = r.get('output') or r.get('target') or r.get('label') or ''
        gt = classify_safe_crisis(r.get('safety'))
        res = call_server(lang,msg)
        if not res.get('ok'):
            errors+=1; continue
        data=res.get('data') or {}
        resp_text = data.get('response') or data.get('reply') or data.get('text') or ''
        src = data.get('source') or data.get('engine') or 'server'
        src_counts[src]=src_counts.get(src,0)+1
        if ref and resp_text==ref: exact+=1
        sims_sum += bigram_overlap(resp_text,ref) if ref else 0.0
        lens_cnt += len(resp_text)
        if gt!='crisis': echo_hits_total += clinical_echo_hits(resp_text)
    n = len(eval_rows)-errors
    if n==0:
        gr={"lang":lang,"n":0,"errors":errors,"exact_match":0.0,"avg_bigram_overlap":0.0,"avg_reply_len":0.0,"clinical_echo_hits":0,"sources":src_counts}
    else:
        gr={
            "lang":lang,"n":n,"errors":errors,
            "exact_match":round(exact/n,4),
            "avg_bigram_overlap":round(sims_sum/n,4),
            "avg_reply_len":round(lens_cnt/n,2),
            "clinical_echo_hits":echo_hits_total,
            "sources":src_counts
        }
    gen_all.append(gr)
    print(json.dumps(gr, ensure_ascii=False, indent=2))

if len(gen_all)>1:
    tot_n=sum(g['n'] for g in gen_all)
    if tot_n>0:
        em=sum(g['exact_match']*g['n'] for g in gen_all)/tot_n
        bo=sum(g['avg_bigram_overlap']*g['n'] for g in gen_all)/tot_n
        al=sum(g['avg_reply_len']*g['n'] for g in gen_all)/tot_n
        eh=sum(g['clinical_echo_hits'] for g in gen_all)
        src_agg={}
        for g in gen_all:
            for k,v in (g['sources'] or {}).items(): src_agg[k]=src_agg.get(k,0)+v
        print("\nGENERATION OVERALL:")
        print(json.dumps({"n":tot_n,"exact_match":round(em,4),"avg_bigram_overlap":round(bo,4),"avg_reply_len":round(al,2),"clinical_echo_hits":eh,"sources":src_agg}, ensure_ascii=False, indent=2))
